#!/usr/bin/env python3
"""Generate the offline browser data and the readable snapshot from reviewed JSON."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
raw = json.loads((ROOT / 'data/opportunities.json').read_text(encoding='utf-8'))
seed = json.loads((ROOT / 'demo/seed.json').read_text(encoding='utf-8'))
jobs = raw['jobs']
if len(jobs) != 20 or len({j['id'] for j in jobs}) != 20 or len({j['url'] for j in jobs}) != 20:
    raise SystemExit('Expected exactly 20 distinct observations')
(ROOT / 'data/bundle.js').write_text(
    '/* Generated by tools/build-data.py. Edit the JSON sources instead. */\n'
    'window.WORKER_SNAPSHOT = ' + json.dumps(raw, ensure_ascii=False, separators=(',', ':')) + ';\n'
    'window.WORKER_DEMO = ' + json.dumps(seed, ensure_ascii=False, separators=(',', ':')) + ';\n', encoding='utf-8')

ranked = sorted(jobs, key=lambda j: (-sum(j['score_parts']), j['id']))
lines = [
 '# AI WORKER — 20 наблюдений и топ-5', '',
 '**Срез на 21.11.2026, UTC.** Это исследование, не список доступных заказов и не прогноз заработка. Данные не обновляются автоматически.', '',
 'В 7 объявлениях Projects.co.id при прямой проверке были видны `Published` и открытый приём предложений. Это наблюдение относится только к дате проверки, а не к текущему моменту. Ещё 13 отдельных страниц Freelancehunt напрямую подтверждали существование и показывали счётчики, однако подробности/бюджет/срок взяты из поискового индекса; актуальность и открытый приём не подтверждены. Индекс может отставать. Счётчик откликов не доказывает открытый приём.', '',
 '**Возрастной допуск и права — отдельно от рейтинга.** Freelancehunt пишет о работе на площадке с 18 лет; условия Projects.co.id допускают индивидуальных пользователей старше 17 лет. В обоих случаях участие несовершеннолетнего младшего возраста не подтверждено; чужой аккаунт не использовать. Также нужны разъяснения Arena о допустимости использования и коммерческих правах на Output, а также проверка условий заказчика, платформы и оплаты. Не передавать созданные здесь материалы заказчикам и не использовать их коммерчески до прояснения прав.', '',
 'Число **отправленных в рамках этой работы заявок — 0**, заказов — 0, фактического дохода — 0. Никаких клиентских вложений, сообщений или ставок не создано.', '',
 '## Как читать рейтинг', '',
 'Каждый проект субъективно оценён по четырём критериям от 0 до 25: ясность доступного брифа, выполнимость учебного разбора, проверяемость результата, ясность экономики. Сумма от 0 до 100; одинаковые баллы сортируются по ID. Это ранжирование **учебного интереса**, не вероятность выигрыша, не финансовый прогноз и не рекомендация участвовать. Неполные ТЗ и незнакомый язык ограничивают точность оценок.', '',
 'Комиссия Projects.co.id 12% — иллюстрация по опубликованным условиям на дату проверки, а не чистая прибыль: другие комиссии, затраты, налоги и курс не установлены. В Freelancehunt значения в USD — отображение в поисковом индексе, возможна конвертация; суммы в чужих откликах не являются бюджетом клиента. Время Freelancehunt приведено без подтверждённого часового пояса. На Projects.co.id `Select Deadline` — срок выбора исполнителя (WIB, UTC+7), `Finish Days` — отдельный срок исполнения.', '',
 '## Топ-5 для изучения', '',
 '| № | Объявление | Оценка | Наблюдение | Основной риск |',
 '|---|---|---:|---|---|',
]
for i,j in enumerate(ranked[:5],1):
    state = 'Открыто 21.11, прямая проверка' if j['verification']=='direct_open' else 'Статус не подтверждён, индекс'
    lines.append(f"| {i} | [{j['title']}]({j['url']}) · {j['platform']} | {sum(j['score_parts'])}/100 | {state} | {j['risk']} |")
lines += ['', '## Все наблюдения', '']
for i,j in enumerate(ranked,1):
    state = 'прямо открыто на дату проверки' if j['verification']=='direct_open' else 'страница найдена; содержание в индексе, статус не подтверждён'
    scores = ' / '.join(map(str,j['score_parts']))
    lines += [f"### {i}. [{j['title']}]({j['url']})", '',
      f"- Источник: {j['platform']} · ID {j['id']} · {state}.",
      f"- Бюджет: {j['budget']}. Срок: {j['deadline']}. Срок работы: {j['work_deadline']}.",
      f"- Содержание: {j['requirements']}",
      f"- Объём и риск: {j['difficulty']}; {j['risk']}",
      f"- Экономика: {j['economics']}",
      f"- Баллы (ясность / выполнимость / проверка / экономика): {scores} = **{sum(j['score_parts'])}/100**. Откликов на дату наблюдения: {j['proposals']}.", '']
lines += [
 '## Условия и источники', '',
 '- [Freelancehunt: об ограничении возраста](https://freelancehunt.com/blog/yak-navchyty-ditei-zarobliaty-online/).',
 '- [Projects.co.id: условия §§2.1, 2.4, 3.4](https://projects.co.id/public/pages/syarat_layanan).',
 '- [Arena: условия, в частности §§3.5 и 5](https://help.arena.ai/articles/5629909088-terms-of-use) и [политика конфиденциальности](https://help.arena.ai/articles/3765052346-privacy-policy).',
 '- Учебный пример основан на общей идее учёта брака, не использует материалы клиента и не является выполненным клиентским заказом. См. `demo/`.',
 '']
(ROOT / 'ОБЗОР-20.md').write_text('\n'.join(lines), encoding='utf-8')
print('Generated data/bundle.js and ОБЗОР-20.md')
